    // state has ended, and is not there to take it (W3C SCXML C.1).
    fn deliver_to_invocation(
        &mut self,
        invoke_id: &str,
        event_name: &str,
        event_data: &str,
    ) -> bool {
        if invoke_id == "kid" {
            if let Some(ref mut child) = self.child_kid {
                if !child.is_in_final_state() {
                    child.deliver_by_name(event_name, event_data);
                    return true;
                }
            }
            return false;
        }
        if invoke_id == "gone" {
            if let Some(ref mut child) = self.child_gone {
                if !child.is_in_final_state() {
                    child.deliver_by_name(event_name, event_data);
                    return true;
                }
            }
            return false;
        }
        false
    }

